{
  "additionalProperties": false,
  "$schema": "http://json-schema.org/schema#",
  "type": "object",
  "properties": {
    "template": {
      "type": "string",
      "description": "The handlebars template resulting in a command."
    },
    "resultParser": {
      "type": "string",
      "description": "The parser able to convert the raw results of this instrument."
    },
    "extension": {
      "type": "string",
      "pattern": "^\\.[a-zA-Z0-9]+$",
      "description": "Possible extension in case of a scriptable instrument."
    },
    "subjectIsLocal": {
      "type": "boolean",
      "description": "Is the subject for this instrument local or remote?"
    },
    "filePath": {
      "$ref": "instrument.schema.json#/properties/filePath"
    },
    "name": {
      "$ref": "type.schema.json#/properties/name"
    },
    "checksum": {
      "$ref": "type.schema.json#/properties/checksum"
    },
    "weight": {
      "$ref": "instrument.schema.json#/properties/weight"
    },
    "arguments": {
      "type": "string",
      "description": "A string representation of the arguments object."
    },
    "desc": {
      "$ref": "type.schema.json#/properties/desc"
    }
  },
  "required": [
    "name",
    "desc",
    "filePath",
    "subjectIsLocal",
    "template"
  ]
}
